"use client";

import { useState, useEffect } from "react";
import { Button } from "@/components/ui/button";
import { Card, CardContent } from "@/components/ui/card";
import { motion } from "framer-motion";
import ThreeScene from "./ThreeScene";

function ConsolePanel({ logs }: { logs: string[] }) {
  return (
    <div className="bg-black text-green-400 font-mono text-xs p-2 h-full overflow-y-auto rounded-lg">
      {logs.map((log, i) => (
        <div key={i}>{log}</div>
      ))}
    </div>
  );
}

export default function MapInterface() {
  const [isRightOpen, setIsRightOpen] = useState(false);
  const [settings, setSettings] = useState({
    zoom: 1,
    buildings: true,
    traffic: false,
    weather: false,
    labels: true,
  });

  const [logs, setLogs] = useState<string[]>([]);

  useEffect(() => {
    const originalLog = console.log;

    console.log = (...args: any[]) => {
      setLogs((prev) => {
        const newLogs = [...prev, args.map((a) => String(a)).join(" ")];
        return newLogs.slice(-100);
      });
      originalLog(...args);
    };

    return () => {
      console.log = originalLog;
    };
  }, []);

  const handleChange = (key: string, value: any) => {
    setSettings({ ...settings, [key]: value });
    console.log(`Змінено ${key}: ${value}`);
  };

  return (
    <div className="w-full h-full flex overflow-hidden bg-neutral-900 text-white">
      <div className="w-64 bg-neutral-800 p-4 border-r border-neutral-700 flex flex-col gap-4">
        <h2 className="text-lg font-semibold">Налаштування</h2>
        <Card className="rounded-2xl shadow-sm bg-neutral-900 border border-neutral-600">
          <CardContent className="p-4 flex flex-col gap-4">
            <label className="flex flex-col gap-1 text-sm text-white">
              Масштаб
              <input
                type="range"
                min="1"
                max="10"
                value={settings.zoom}
                onChange={(e) => handleChange("zoom", e.target.value)}
                className="w-full"
              />
            </label>
            <label className="flex gap-2 text-sm items-center text-white">
              <input
                type="checkbox"
                checked={settings.buildings}
                onChange={(e) => handleChange("buildings", e.target.checked)}
              />
              Будівлі
            </label>
            <label className="flex gap-2 text-sm items-center text-white">
              <input
                type="checkbox"
                checked={settings.traffic}
                onChange={(e) => handleChange("traffic", e.target.checked)}
              />
              Трафік
            </label>
            <label className="flex gap-2 text-sm items-center text-white">
              <input
                type="checkbox"
                checked={settings.weather}
                onChange={(e) => handleChange("weather", e.target.checked)}
              />
              Погода
            </label>
            <label className="flex gap-2 text-sm items-center text-white">
              <input
                type="checkbox"
                checked={settings.labels}
                onChange={(e) => handleChange("labels", e.target.checked)}
              />
              Позначки
            </label>
          </CardContent>
        </Card>

        <Button
          onClick={() => setIsRightOpen(true)}
          className="rounded-2xl text-white"
        >
          Інформація
        </Button>
      </div>

      <div className="flex-1 relative">
        <ThreeScene settings={settings} />
      </div>

      <motion.div
        initial={{ x: 400 }}
        animate={{ x: isRightOpen ? 0 : 400 }}
        transition={{ type: "spring", stiffness: 200, damping: 22 }}
        className="w-80 h-full bg-neutral-900 border-l border-neutral-700 p-4 absolute right-0 top-0 flex flex-col gap-4 shadow-xl rounded-l-2xl overflow-y-auto"
      >
        <div className="flex justify-between items-center">
          <h2 className="text-lg font-semibold">Панель даних</h2>
          <Button variant="ghost" onClick={() => setIsRightOpen(false)}>
            Закрити
          </Button>
        </div>

        <div className="flex flex-col gap-2 text-sm">
          <p>Масштаб: {settings.zoom}</p>
          <p>Будівлі: {settings.buildings ? "Увімкнено" : "Вимкнено"}</p>
          <p>Трафік: {settings.traffic ? "Увімкнено" : "Вимкнено"}</p>
          <p>Погода: {settings.weather ? "Увімкнено" : "Вимкнено"}</p>
          <p>Позначки: {settings.labels ? "Увімкнено" : "Вимкнено"}</p>
        </div>

        <h3 className="text-sm font-semibold mt-2">JS Console</h3>
        <ConsolePanel logs={logs} />
      </motion.div>
    </div>
  );
}
