import * as THREE from "three";
import { ExtrudeGeometry } from "three";
import proj4 from "proj4";

const WGS84 = "EPSG:4326";
const WEB_MERCATOR = "EPSG:3857";

export const DEFAULTS = {
  buildingHeight: 50,
  roadY: 0.12,
  roadWidths: {
    motorway: 15,
    trunk: 12,
    primary: 10,
    secondary: 8,
    tertiary: 6,
    residential: 5,
    service: 3,
    path: 2,
    footway: 1.5,
  },
  roadColors: {
    motorway: 0xe892a2,
    trunk: 0xf9b29c,
    primary: 0xfcd6a4,
    secondary: 0xf7fabf,
    tertiary: 0xffffff,
    residential: 0xffffff,
    service: 0xffffff,
    path: 0xc5b3a0,
    footway: 0xc5b3a0,
  },
};

export class LayerRenderer {
  constructor(centerOffset = [0, 0]) {
    this.centerOffset = centerOffset;
  }

  setCenterOffset(offset) {
    this.centerOffset = offset;
  }
  setCenterFromLonLat(lon, lat) {
    const [x, z] = proj4("EPSG:4326", "EPSG:3857", [lon, lat]);
    this.centerOffset = [x, z];
  }

  toLocal(lon, lat) {
    const [x0, z0] = proj4(WGS84, WEB_MERCATOR, [lon, lat]);
    return [x0 - this.centerOffset[0], z0 - this.centerOffset[1]];
  }

  renderFeature() {
    throw new Error("renderFeature must be implemented");
  }
}

class PolygonRendererBase extends LayerRenderer {
  _ensureClosed(ring) {
    if (!Array.isArray(ring) || ring.length < 3) return null;
    const f = ring[0];
    const l = ring[ring.length - 1];
    return f[0] === l[0] && f[1] === l[1] ? ring : [...ring, f];
  }

  _coordsToShape(coords) {
    if (!Array.isArray(coords) || coords.length === 0) return null;

    const outer = this._ensureClosed(coords[0]);
    if (!outer) return null;

    const shape = new THREE.Shape();
    outer.forEach(([lon, lat], i) => {
      const [x, z] = this.toLocal(lon, lat);
      if (!Number.isFinite(x) || !Number.isFinite(z)) return;
      i === 0 ? shape.moveTo(x, z) : shape.lineTo(x, z);
    });

    for (let i = 1; i < coords.length; i++) {
      const hole = this._ensureClosed(coords[i]);
      if (!hole) continue;
      const path = new THREE.Path();
      hole.forEach(([lon, lat], j) => {
        const [x, z] = this.toLocal(lon, lat);
        if (!Number.isFinite(x) || !Number.isFinite(z)) return;
        j === 0 ? path.moveTo(x, z) : path.lineTo(x, z);
      });
      shape.holes.push(path);
    }

    return shape;
  }
}

export class BuildingsRenderer extends PolygonRendererBase {
  renderFeature({ geometry, properties = {} }) {
    if (!geometry) return [];
    const height = Number(properties.height) || DEFAULTS.buildingHeight;
    const meshes = [];

    const build = (coords) => {
      const shape = this._coordsToShape(coords);
      if (!shape) return;

      const g = new ExtrudeGeometry(shape, {
        depth: height,
        bevelEnabled: false,
      });
      g.rotateX(-Math.PI / 2);
      g.computeBoundingBox();
      g.computeBoundingSphere();

      const m = new THREE.Mesh(
        g,
        new THREE.MeshStandardMaterial({
          color: 0xcccccc,
          roughness: 0.8,
          metalness: 0.2,
        })
      );

      m.castShadow = true;
      m.receiveShadow = true;
      meshes.push(m);
    };

    geometry.type === "Polygon"
      ? build(geometry.coordinates)
      : geometry.coordinates.forEach(build);

    return meshes;
  }
}

export class RiversRenderer extends PolygonRendererBase {
  renderFeature({ geometry }) {
    if (!geometry) return [];
    const meshes = [];

    const build = (coords) => {
      const shape = this._coordsToShape(coords);
      if (!shape) return;

      const g = new THREE.ShapeGeometry(shape);
      g.rotateX(-Math.PI / 2);
      g.computeBoundingBox();
      g.computeBoundingSphere();

      const m = new THREE.Mesh(
        g,
        new THREE.MeshStandardMaterial({
          color: 0xaaddff,
          roughness: 0.6,
          metalness: 0.1,
          side: THREE.DoubleSide,
        })
      );

      m.receiveShadow = true;
      meshes.push(m);
    };

    geometry.type === "Polygon"
      ? build(geometry.coordinates)
      : geometry.coordinates.forEach(build);

    return meshes;
  }
}

export class RoadsRenderer extends LayerRenderer {
  renderFeature({ geometry, properties = {} }) {
    if (!geometry) return [];
    const meshes = [];

    const handle = (coords) => {
      const m = this._lineToMesh(coords, properties);
      if (m) meshes.push(m);
    };

    geometry.type === "LineString"
      ? handle(geometry.coordinates)
      : geometry.coordinates.forEach(handle);

    return meshes;
  }

  _resolveRoadType(props) {
    return props?.fclass || props?.highway || props?.type || "residential";
  }

  _lineToMesh(coords, props) {
    if (!Array.isArray(coords) || coords.length < 2) return null;

    const type = this._resolveRoadType(props);
    const width = DEFAULTS.roadWidths[type] ?? 5;
    if (!Number.isFinite(width)) return null;

    const y = DEFAULTS.roadY;
    const pts = [];

    for (const [lon, lat] of coords) {
      const [x, z] = this.toLocal(lon, lat);
      if (!Number.isFinite(x) || !Number.isFinite(z)) continue;
      pts.push(new THREE.Vector3(x, y, z));
    }

    if (pts.length < 2) return null;

    const positions = [];
    const indices = [];

    for (let i = 0; i < pts.length - 1; i++) {
      const a = pts[i];
      const b = pts[i + 1];

      const dir = b.clone().sub(a);
      if (dir.lengthSq() === 0) continue;
      dir.normalize();

      const perp = new THREE.Vector3(-dir.z, 0, dir.x).multiplyScalar(
        width / 2
      );

      const base = positions.length / 3;

      [
        a.clone().add(perp),
        a.clone().sub(perp),
        b.clone().add(perp),
        b.clone().sub(perp),
      ].forEach((v) => positions.push(v.x, v.y, v.z));

      indices.push(base, base + 1, base + 2, base + 1, base + 3, base + 2);
    }

    if (!positions.length) return null;

    const g = new THREE.BufferGeometry();
    g.setAttribute("position", new THREE.Float32BufferAttribute(positions, 3));
    g.setIndex(indices);
    g.computeVertexNormals();
    g.computeBoundingBox();
    g.computeBoundingSphere();

    const m = new THREE.Mesh(
      g,
      new THREE.MeshStandardMaterial({
        color: DEFAULTS.roadColors[type] ?? 0xdddddd,
        roughness: 1,
        metalness: 0,
        polygonOffset: true,
        polygonOffsetFactor: -3,
        polygonOffsetUnits: -3,
        side: THREE.DoubleSide,
      })
    );

    m.rotation.x = -Math.PI;
    m.frustumCulled = false;

    return m;
  }
}

export const RENDERERS = {
  buildings: BuildingsRenderer,
  roads: RoadsRenderer,
  rivers: RiversRenderer,
};
